package com.medicine.reminder.service;
import com.medicine.reminder.model.*; import com.medicine.reminder.repository.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.web.server.ResponseStatusException; import java.time.*; import java.util.*;
@Service public class HistoryService {private final HistoryRepository history;private final ReminderRepository reminders;private final MedicineService medicines;public HistoryService(HistoryRepository h,ReminderRepository r,MedicineService m){history=h;reminders=r;medicines=m;}
 public List<MedicineHistory> list(Long profileId){return history.findByReminderMedicineProfileIdOrderByTakenAtDesc(profileId);} public MedicineHistory log(Long reminderId,String status,Long uid){Reminder r=owned(reminderId,uid);if(!Set.of("TAKEN","SKIPPED","MISSED").contains(status))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid history status");LocalDateTime s=LocalDate.now().atStartOfDay(),e=s.plusDays(1);var existing=history.findToday(r.getId(),s,e);MedicineHistory h=existing.isEmpty()?new MedicineHistory():existing.get(0);boolean newlyTaken="TAKEN".equals(status)&&(existing.isEmpty()||!"TAKEN".equals(h.getStatus()));h.setReminder(r);h.setStatus(status);h.setTakenAt(LocalDateTime.now());MedicineHistory saved=history.save(h);if(newlyTaken)medicines.decrementStock(r.getMedicine().getId());return saved;} public boolean hasToday(Long reminderId){LocalDateTime s=LocalDate.now().atStartOfDay();return !history.findToday(reminderId,s,s.plusDays(1)).isEmpty();} public MedicineHistory today(Long id){LocalDateTime s=LocalDate.now().atStartOfDay();var l=history.findToday(id,s,s.plusDays(1));return l.isEmpty()?null:l.get(0);} private Reminder owned(Long id,Long u){return reminders.findByIdAndMedicineProfileUserId(id,u).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Reminder not found"));}}
